<?php
namespace App\Http\Controllers;
use App\Models\{Contact,Account};use Illuminate\Http\Request;
class ContactController {public function index(){return view('contacts.index',['contacts'=>Contact::forCompany(auth()->user()->company_id)->orderBy('name')->get(),'accounts'=>Account::forCompany(auth()->user()->company_id)->where('is_postable',1)->orderBy('code')->get()]);}public function store(Request $r){$d=$r->validate(['type'=>'required|in:customer,supplier,both','name'=>'required|string|max:255','tax_number'=>'nullable|string|max:100','email'=>'nullable|email','phone'=>'nullable|string|max:50','address'=>'nullable|string|max:500','receivable_account_id'=>'nullable|integer','payable_account_id'=>'nullable|integer']);$d['company_id']=$r->user()->company_id;foreach(['receivable_account_id','payable_account_id'] as $k)if(!empty($d[$k]))Account::forCompany($d['company_id'])->findOrFail($d[$k]);Contact::create($d);return back()->with('ok','Contact created.');}public function update(Request $r,Contact $contact){$d=$r->validate(['name'=>'required|string|max:255','tax_number'=>'nullable|string|max:100','email'=>'nullable|email','phone'=>'nullable|string|max:50','address'=>'nullable|string|max:500','active'=>'nullable|boolean']);$d['active']=$r->boolean('active');$contact->update($d);return back()->with('ok','Contact updated.');}}
